WITH filtered_stores AS (SELECT *, TRIM(region) AS clean_region FROM stores WHERE region = 'South' AND opened_date BETWEEN '2024-02-01' AND '2025-05-01'), stores_stats AS (SELECT region, city, ROUND((100 * SUM(CASE WHEN region = 'North' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_north, SUM(sqft) AS total_sqft FROM filtered_stores GROUP BY region, city) SELECT region, city, pct_north, total_sqft FROM stores_stats WHERE total_sqft >= 37000 ORDER BY total_sqft DESC;
